import styled from '@emotion/styled';
import * as AlertDialog from '@radix-ui/react-alert-dialog';
import { theme } from 'theme';
import { transientShouldForwardProp } from 'utils/emotion';

import type { ModalVariant } from './Modal.types';

const TABLET_BREAKPOINT = '56.25rem';

interface StyledModalContentProps {
  $variant: ModalVariant;
}

interface StyledDialogHeaderProps {
  $hasImage: boolean;
  $headerHeight?: string;
}

interface StyledDialogTitleProps {
  $shouldAdjustPadding: boolean;
}

interface StyledDialogBodyProps {
  $adjustTopPadding: boolean;
  $adjustRightPadding: boolean;
}

export const StyledOverlay = styled(AlertDialog.Overlay)({
  backgroundColor: 'rgba(0, 0, 0, 0.5)',
  inset: 0,
  position: 'fixed',
  zIndex: 3995,
});

export const StyledModalContent = styled(AlertDialog.Content, {
  shouldForwardProp: transientShouldForwardProp,
})<StyledModalContentProps>(({ $variant }) => ({
  backgroundColor: theme.colors.neutral0,
  bottom: '0%',
  boxShadow: '0 4px 16px rgba(0, 0, 0, 0.16)',
  display: 'flex',
  flexDirection: 'column',
  left: '0%',
  maxHeight: '95%',
  minWidth: '100%',
  position: 'fixed',
  zIndex: 4000,
  borderTopLeftRadius: theme.borderRadius['8'],
  borderTopRightRadius: theme.borderRadius['8'],
  ...($variant === 'overlay' && {
    [`@media (min-width: ${TABLET_BREAKPOINT})`]: {
      borderRadius: theme.borderRadius['6'],
      bottom: 'auto',
      left: '50%',
      minWidth: '28rem',
      top: '50%',
      transform: 'translate3d(-50%, -50%, 0)',
    },
  }),
  ...($variant === 'bottomTray' && {
    height: '95%',
    [`@media (min-width: ${TABLET_BREAKPOINT})`]: {
      borderTopLeftRadius: theme.borderRadius['6'],
      borderTopRightRadius: theme.borderRadius['6'],
    },
  }),
  ...($variant === 'takeOver' && {
    borderRadius: theme.borderRadius.none,
    height: '100%',
    width: '100%',
  }),
}));

export const StyledCriticalLine = styled('hr')({
  borderTop: `0.625rem dashed ${theme.colors.semanticErrorText}`,
  margin: '0 1.25rem',
  transform: 'skew(340deg)',
});

export const StyledDialogHeader = styled('div')<StyledDialogHeaderProps>(
  ({ $hasImage, $headerHeight }) => ({
    borderRadius: theme.borderRadius['6'],
    marginBottom: theme.spacing['4'],
    ...($hasImage
      ? { minHeight: '6.25rem' }
      : { height: $headerHeight ?? '4rem' }),
  }),
);

export const StyledDialogTitle = styled('div')<StyledDialogTitleProps>(
  ({ $shouldAdjustPadding }) => ({
    marginRight: theme.spacing['16'],
    padding: $shouldAdjustPadding
      ? `${theme.spacing['8']} ${theme.spacing['16']} 0 ${theme.spacing['8']}`
      : `${theme.spacing['8']} ${theme.spacing['8']} 0`,
    width: '100%',
  }),
);

export const StyledDialogBody = styled('div')<StyledDialogBodyProps>(
  ({ $adjustTopPadding, $adjustRightPadding }) => ({
    marginBottom: theme.spacing['8'],
    overflowY: 'auto',
    paddingLeft: theme.spacing['8'],
    paddingTop: $adjustTopPadding ? theme.spacing['8'] : '0',
    paddingRight: $adjustRightPadding
      ? theme.spacing['16']
      : theme.spacing['8'],
  }),
);

export const StyledDialogActions = styled('div')({
  padding: `0 ${theme.spacing['8']} ${theme.spacing['8']}`,
  width: '100%',
});
